package com.universe.school.service; import com.universe.school.dto.response.SchoolResponse; import com.universe.school.entity.SchoolStatus; import com.universe.school.repository.SchoolRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; @Service @RequiredArgsConstructor public class SchoolService {private final SchoolRepository schools; @Transactional(readOnly=true) public List<SchoolResponse> find(String keyword){var list=keyword==null||keyword.isBlank()?schools.findByStatusOrderBySchoolNameAsc(SchoolStatus.ACTIVE):schools.findByStatusAndSchoolNameContainingIgnoreCaseOrderBySchoolNameAsc(SchoolStatus.ACTIVE,keyword); return list.stream().map(SchoolResponse::from).toList();}}
